import { LinearProgress } from '@mui/material';
import { SimplifiedUpload } from './SimplifiedUpload';
import Upload from './Upload';
import { useSiteModel } from './useSiteModel';

type UploadPageProps = {
    isFirstFile: boolean;
    onOpenWizard?: () => void;
};

/**
 * The simplified page on a site generated by the wizard (its model is known),
 * the full one otherwise.
 */
export const UploadPage = ({ isFirstFile, onOpenWizard }: UploadPageProps) => {
    const { isLoading, siteModel } = useSiteModel();

    if (isLoading) {
        // the same bar as withInitialData: one progress from the page load
        return <LinearProgress />;
    }

    if (siteModel) {
        return (
            <SimplifiedUpload
                model={siteModel.model}
                hasData={!isFirstFile}
                onOpenWizard={onOpenWizard}
            />
        );
    }

    return (
        <Upload
            // @ts-expect-error TS2322
            className="admin"
            isFirstFile={isFirstFile}
            onOpenWizard={onOpenWizard}
        />
    );
};
